import type { ChaosPatron, ChosenPatron } from "../../../types/mutants-handbook";
import type { WfrpActor, WfrpMutationItem } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import {
  CHOSEN_PATRON_FLAG,
  CHOSEN_PATRON_MARKER_FLAG,
  CHOSEN_PATRON_TRAIT_IDS,
} from "./constants";
import { normalizeName } from "./document-helpers";
import { updateActor } from "./updates";

const CHAOS_PATRONS: ChaosPatron[] = ["khorne", "nurgle", "slaanesh", "tzeentch"];

export function chosenPatronName(patron: ChaosPatron): string {
  return `Chosen of ${patron.charAt(0).toUpperCase()}${patron.slice(1)}`;
}

function markerPatron(item: WfrpMutationItem): ChaosPatron | undefined {
  if (item.type !== "trait") return undefined;
  const flagged =
    typeof item.getFlag === "function"
      ? item.getFlag(MODULE_ID, CHOSEN_PATRON_MARKER_FLAG)
      : item.flags?.[MODULE_ID]?.[CHOSEN_PATRON_MARKER_FLAG];
  const byFlag = CHAOS_PATRONS.find((patron) => patron === flagged);
  if (byFlag) return byFlag;
  return CHAOS_PATRONS.find(
    (patron) => normalizeName(item.name) === normalizeName(chosenPatronName(patron)),
  );
}

export function getChosenPatrons(actor: WfrpActor): ChaosPatron[] {
  return [
    ...new Set(
      Array.from(actor.items)
        .map(markerPatron)
        .filter((patron): patron is ChaosPatron => patron !== undefined),
    ),
  ];
}

export function getLegacyChosenPatron(actor: WfrpActor): ChosenPatron | undefined {
  if (typeof actor.getFlag !== "function") return undefined;
  const value = actor.getFlag(MODULE_ID, CHOSEN_PATRON_FLAG);
  if (value === "unassigned") return value;
  return CHAOS_PATRONS.find((patron) => patron === value);
}

export function getChosenPatron(actor: WfrpActor): ChosenPatron | undefined {
  const patrons = getChosenPatrons(actor);
  if (patrons.length === 1) return patrons[0];
  if (patrons.length > 1) return undefined;
  return getLegacyChosenPatron(actor);
}

export async function addChosenPatronTrait(actor: WfrpActor, patron: ChaosPatron): Promise<void> {
  if (getChosenPatrons(actor).includes(patron)) {
    await clearLegacyChosenPatron(actor);
    return;
  }

  const uuid = `Compendium.${MODULE_ID}.ratter-11-items.Item.${CHOSEN_PATRON_TRAIT_IDS[patron]}`;
  const source = (await fromUuid(uuid)) as WfrpMutationItem | undefined;
  if (!source || source.type !== "trait") {
    throw new Error(`The required ${chosenPatronName(patron)} Trait is unavailable.`);
  }
  const data = source.toObject();
  delete data["_id"];
  delete data["_key"];
  const created = await actor.createEmbeddedDocuments("Item", [data], {
    skipSpecialisationChoice: true,
  });
  if (created.length !== 1) {
    throw new Error(
      `Foundry prevented ${chosenPatronName(patron)} from being added to ${actor.name}.`,
    );
  }
  await clearLegacyChosenPatron(actor);
}

export async function clearLegacyChosenPatron(actor: WfrpActor): Promise<void> {
  if (getLegacyChosenPatron(actor) === undefined) return;
  await updateActor(actor, { [`flags.${MODULE_ID}.-=${CHOSEN_PATRON_FLAG}`]: null });
}

export async function migrateLegacyChosenPatron(actor: WfrpActor): Promise<void> {
  const patron = getLegacyChosenPatron(actor);
  if (patron && patron !== "unassigned" && getChosenPatrons(actor).length === 0) {
    await addChosenPatronTrait(actor, patron);
  }
}
