import type { WfrpActor } from "../../../types/foundry";

export async function updateActor(
  actor: WfrpActor,
  changes: Record<string, unknown>,
): Promise<void> {
  const updatedActor = await actor.update(changes, { skipCorruption: true });

  if (!updatedActor) {
    throw new Error(`Foundry prevented the required update to ${actor.name}.`);
  }
}
