import type { ChaosPatron, HandbookSpecies } from "../../../types/mutants-handbook";
import type { MutationAcquisitionBlock } from "./documents";

const SPECIES: HandbookSpecies[] = ["human", "dwarf", "elf", "halfling", "gnome", "ogre"];
const PATRONS: ChaosPatron[] = ["khorne", "nurgle", "slaanesh", "tzeentch"];

export type MutationBlockAction = "accept" | "cancel" | "reroll";

function capitalize(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export async function chooseMutationBlockAction(
  mutationName: string,
  block: MutationAcquisitionBlock,
  canReroll: boolean,
): Promise<MutationBlockAction> {
  const buttons = [
    ...(canReroll
      ? [
          {
            action: "reroll",
            callback: () => "reroll",
            default: true,
            label: "Reroll",
          },
        ]
      : []),
    {
      action: "accept",
      callback: () => "accept",
      default: !canReroll,
      label: "Accept Anyway",
    },
    { action: "cancel", callback: () => "cancel", label: "Cancel" },
  ];
  const choice = await foundry.applications.api.DialogV2.wait({
    buttons,
    content: `<div class="fvtt-wfrp-ratter-root"><div role="alert" class="tw:dui-alert tw:dui-alert-warning"><span>${escapeHtml(block.message)}</span></div><p>${canReroll ? "Reroll this table result, accept it despite the warning, or cancel the mutation procedure." : "Accept this mutation despite the warning, or cancel adding it."}</p></div>`,
    rejectClose: false,
    window: { title: `Review ${mutationName}` },
  });

  return choice === "accept" || choice === "reroll" ? choice : "cancel";
}

export async function chooseHandbookSpecies(
  actorName: string,
  currentSpecies: string,
): Promise<HandbookSpecies | undefined> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while choosing a species profile.");
  }

  const choice = await foundry.applications.api.DialogV2.wait({
    buttons: SPECIES.map((species) => ({
      action: species,
      label: capitalize(species),
    })),
    content: game.i18n.format("FVTT_WFRP_RATTER.Mutations.UnknownSpeciesPrompt", {
      name: actorName,
      species: currentSpecies || game.i18n.localize("FVTT_WFRP_RATTER.Mutations.UnknownSpecies"),
    }),
    rejectClose: false,
    window: {
      title: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.UnknownSpeciesTitle"),
    },
  });

  return SPECIES.find((species) => species === choice);
}

export async function chooseChaosPatron(actorName: string): Promise<ChaosPatron | undefined> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while choosing a Chaos patron.");
  }

  const choice = await foundry.applications.api.DialogV2.wait({
    buttons: PATRONS.map((patron) => ({
      action: patron,
      label: capitalize(patron),
    })),
    content: game.i18n.format("FVTT_WFRP_RATTER.Mutations.PatronPrompt", {
      name: actorName,
    }),
    rejectClose: true,
    window: {
      title: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.PatronTitle"),
    },
  });

  return PATRONS.find((patron) => patron === choice);
}

export async function spendResilience(actorName: string, outcomeName: string): Promise<boolean> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while spending Resilience.");
  }

  const choice = await foundry.applications.api.DialogV2.confirm({
    content: game.i18n.format("FVTT_WFRP_RATTER.Mutations.ResiliencePrompt", {
      mutation: outcomeName,
      name: actorName,
    }),
    no: {
      label: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.KeepMutation"),
    },
    rejectClose: false,
    window: {
      title: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.ResilienceTitle"),
    },
    yes: {
      label: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.SpendResilience"),
    },
  });

  return choice === true;
}

export async function addRepeatedMutation(
  actorName: string,
  mutationName: string,
): Promise<boolean> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while reviewing a repeated mutation.");
  }

  const choice = await foundry.applications.api.DialogV2.confirm({
    content: game.i18n.format("FVTT_WFRP_RATTER.Mutations.RepeatPrompt", {
      mutation: mutationName,
      name: actorName,
    }),
    no: {
      default: false,
      label: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.ResolveManually"),
    },
    rejectClose: false,
    window: {
      title: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.RepeatTitle"),
    },
    yes: {
      default: true,
      label: game.i18n.localize("FVTT_WFRP_RATTER.Mutations.AddOccurrence"),
    },
  });

  return choice === true;
}
